        var p=player(h);PowerAttributes.set(p,"f:tin",2);TinFeruchemy.sense(p,1);var mind=jewelry("tin","ring");Metalminds.transfer(mind,p.getUUID(),"tin:hearing",100);p.setItemInHand(InteractionHand.OFF_HAND,mind);PowerData.state(p,"f:tin",4);TinFeruchemy.tick(p);h.assertTrue(TinService.revealStrength(p)==0,"Hearing belowtap5 gives no pulses");
