        Metalminds.transfer(mind,p.getUUID(),"tin:sight",-1000);Metalminds.transfer(mind,p.getUUID(),"tin:sight",.001);PowerData.state(p,"f:tin",20);TinFeruchemy.tick(p);h.assertTrue(TinFeruchemy.factor(p,true)>1&&TinFeruchemy.factor(p,true)<1.1,"Partial reserve gives only funded sensory enhancement");TinFeruchemy.tick(p);h.assertTrue(TinFeruchemy.factor(p,true)==1,"Depletion removes enhanced sight");h.succeed();
