        long now=p.level().getGameTime();StorageActivity.observe(p,now);for(int i=1;i<=6001;i++)StorageActivity.observe(p,now+i);PowerData.state(p,"f:brass",-5);BrassFeruchemy.tick(p);h.assertTrue(Metalminds.charge(mind)==0&&BrassFeruchemy.fireReduction(p)==0,"Idle storage cannot grant free fire immunity");
